!function(e){function t(t){for(var a,i,o=t[0],d=t[1],m=t[2],c=0,f=[];c<o.length;c++)i=o[c],Object.prototype.hasOwnProperty.call(n,i)&&n[i]&&f.push(n[i][0]),n[i]=0;for(a in d)Object.prototype.hasOwnProperty.call(d,a)&&(e[a]=d[a]);for(s&&s(t);f.length;)f.shift()();return p.push.apply(p,m||[]),r()}function r(){for(var e,t=0;t<p.length;t++){for(var r,i=p[t],o=!0,d=1;d<i.length;d++)r=i[d],0!==n[r]&&(o=!1);o&&(p.splice(t--,1),e=a(a.s=i[0]))}return e}function a(t){if(i[t])return i[t].exports;var r=i[t]={i:t,l:!1,exports:{}};return e[t].call(r.exports,r,r.exports,a),r.l=!0,r.exports}var i={},n={19:0},p=[];a.m=e,a.c=i,a.d=function(e,t,r){a.o(e,t)||Object.defineProperty(e,t,{enumerable:!0,get:r})},a.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},a.t=function(e,t){if(1&t&&(e=a(e)),8&t)return e;if(4&t&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(a.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&t&&"string"!=typeof e)for(var i in e)a.d(r,i,function(t){return e[t]}.bind(null,i));return r},a.n=function(e){var t=e&&e.__esModule?function(){return e.default}:function(){return e};return a.d(t,"a",t),t},a.o=function(e,t){return Object.prototype.hasOwnProperty.call(e,t)},a.p="";var o=window.webpackJsonp=window.webpackJsonp||[],d=o.push.bind(o);o.push=t,o=o.slice();for(var m=0;m<o.length;m++)t(o[m]);var s=d;p.push([120,0]),r()}({120:function(e,t,r){"use strict";r.r(t);var a=r(0);Object(a.a)("de","army",r(121),r(1))},121:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"半履带装甲车辆","link":"de_army#de_army_avhtv"}],"model":"251/4型半履带装甲火炮牵引（弹药运载）车","description":"<p>二战初期，德军部队中自行炮车较少，很多地面火炮要靠马匹拉动，机动性和防卫性都很差，为了改变这种情况，德军用部分251车体改装为专用的火炮牵引车，正式定名Sdkfz 251/4型半履带装甲火炮牵引车。由于251车体具有一定的装甲防护，因而在牵引火炮进入战场途中能抵挡轻武器的射击，生存力相比马匹和无装甲的运输车要强。</p><p>251/4有较高的车速和行程，所以能使德军炮兵部队跟上装甲部队快速行进，在二战初期对德军闪电战的成功实施起了重要作用。但随着后来德军大量自行炮车的产生，需要牵引的火炮日益减少，251/4火炮牵引车的作用就慢慢减退了。</p><p>为了给被牵引的火炮提供炮弹，部分251/4改装为弹药运载车，装载被牵引火炮的弹药跟随牵引车同行；到了二战中后期，随着251/4牵引作用的减少，251/4则改装为弹药运载车用，1943年定名为Sdkfz 251/4 Ⅱ型半履带装甲弹药运载车，该车主要配备给坦克部队，为坦克运载炮弹和作战场弹药补给。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_avhtv2514_11.jpg","description":"<h6>Sdkfz 251/4型半履带装甲火炮牵引车</h6><p>Sdkfz 251/4型多数用251早期生产的A、B、C车体改装，车上大多不配备专用武器，但后期也有一些配备一挺高射机枪作防空用；该车车厢上方用帆布遮盖，车厢内可乘坐炮组成员7～8人。</p><p>该车具有较大的牵引力，通常用来牵引轻型与重型的步兵炮、轻型与中型的反坦克炮、轻型防空炮或轻型榴弹炮等火炮。</p>","caption":""},{"image":"imgs/de/army/de_army_avhtv2514_12.jpg","description":"<h6>Sdkfz 251/4 Ⅱ型半履带装甲弹药运载车</h6><p>Sdkfz 251/4 Ⅱ型半履带装甲弹药运载车主要用251 C、D车体改装，车上会配备1～2挺机枪；该车车厢拆除了全部座位用来放置坦克炮弹，车上乘员一般为3人，1人为驾驶员，另2人为弹药手；车厢上方用装甲封闭以加强防护；为了保持与坦克的联络，车内配备一台FuG 5型通讯电台，车外安装有一根2米标准天线。</p>","caption":""}],"part2title":"战场上的251/4型半履带装甲火炮牵引（弹药运载）车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_avhtv2514_21.jpg","description":"1945年3月，东线战场匈牙利地区，隶属德军第1装甲师第113装甲炮兵团的一辆 Sdkfz 251/4 Ausf A型半履带装甲火炮牵引车。该车安装了前置机枪，车厢上方布罩已拆除，可能已作运兵与牵引两用了。","caption":""},{"image":"imgs/de/army/de_army_avhtv2514_22.jpg","description":"1941年7月，在入侵苏联的巴巴罗萨行动中，一辆德军Sdkfz 251/4 Ausf A型半履带装甲火炮牵引车。该车正牵引着一门LefH 18型105mm轻榴弹炮在草原上行驶。","caption":""},{"image":"imgs/de/army/de_army_avhtv2514_23.jpg","description":"1940年5月，西线战场法国地区，一辆德军第7装甲师炮兵团的Sdkfz 251/4 Ausf A型半履带装甲火炮牵引车牵引着一门105mm口径LeFH 18型轻榴弹炮与多辆德军坦克一起向前线进发。","caption":""},{"image":"imgs/de/army/de_army_avhtv2514_24.jpg","description":"1944年夏天，西线战场，一辆Sdkfz 251/4 Ausf D型半履带装甲火炮牵引车牵引着一门75mm口径Pak 40型中型反坦克炮行驶在公路上。","caption":""},{"image":"imgs/de/army/de_army_avhtv2514_25.jpg","description":"一辆牵引着一门105mm口径LeFH 18型轻榴弹炮的德军Sdkfz 251/4 Ausf B型半履带装甲火炮牵引车正在涉水越过小河。","caption":""},{"image":"imgs/de/army/de_army_avhtv2514_26.jpg","description":"1940年5月，西线战场法国，德军强渡马斯河战役，德军第7装甲师第78炮兵团的一辆Sdkfz 251/4 Ausf A型半履带装甲火炮牵引车，该车牵引着一门105mm口径LeFH 18型轻榴弹炮向前线进发。","caption":""},{"image":"imgs/de/army/de_army_avhtv2514_27.jpg","description":"一辆牵引着一门150mm口径SLG 33型重步兵炮的德军Sdkfz 251/4 Ausf A型半履带装甲火炮牵引车。","caption":""},{"image":"imgs/de/army/de_army_avhtv2514_28.jpg","description":"1942年，北非战场上一辆隶属德国非洲军团的Sdkfz 251/4 Ausf A型半履带装甲火炮牵引车牵引着一门50mmPak 38型轻型反坦克弹炮在崎岖的路上行进。","caption":""},{"image":"imgs/de/army/de_army_avhtv2514_29.jpg","description":"1943年秋天，东线苏联战场，一辆德军Sdkfz 251/4型半履带装甲火炮牵引车牵引着一门缴获的苏军76.2mm口径F22USV M1939型野战炮行驶在农村泥路上。二战中，德军将不少缴获的苏军火炮都装备到自己部队中，该型野战炮被德军命名为Pak-38。","caption":""},{"image":"imgs/de/army/de_army_avhtv2514_30.jpg","description":"1943年，东线苏联库尔斯克战场上，一辆德军的Sdkfz 251/4 Ausf A型半履带装甲火炮牵引车正驶近一门苏军遗弃的76.5mm口径Zis-3 M1942型野战炮，准备将其牵引作德军火炮用。","caption":""},{"image":"imgs/de/army/de_army_avhtv2514_31.jpg","description":"1943年冬天，东线苏联战场上的一辆德军Sdkfz 251/4 Ausf C型半履带装甲弹药运载车。该车是专门负责为德军坦克运载炮弹，并承担在战场上为坦克作弹药补给的任务。","caption":""},{"image":"imgs/de/army/de_army_avhtv2514_32.jpg","description":"图中左边是一辆德军作弹药运载用的Sdkfz 251/4 Ausf D型半履带装甲车，车组的弹药手正在将炮弹传送给一辆虎式坦克作弹药补给。","caption":""}]}')}});